"""Build a creator-first Sardinia watch guide from reviewed source records."""
import json
from html import escape as e
from pathlib import Path
from urllib.parse import quote
ROOT=Path(__file__).resolve().parent.parent

def main():
    creators=json.loads((ROOT/'data/creators.json').read_text())
    meta={x['id']:x for x in json.loads((ROOT/'docs/research/sardinia-local-review-2026-10-23.json').read_text())}
    meta.update({x['id']:x for x in json.loads((ROOT/'docs/research/sardinia-review-2026-10-23.json').read_text())})
    selection=json.loads((ROOT/'data/sardinia-guide.json').read_text())
    def card(x):
        m=meta[x['id']];c=creators[x['creator']];url='https://www.youtube.com/watch?v='+x['id'];seconds=int(m.get('duration') or 0);duration=f'{seconds//60}:{seconds%60:02d}' if seconds else ''
        return f'''<article><a href="{url}" class="thumb" aria-label="Watch {e(m['title'],quote=True)}"><img loading="lazy" src="https://i.ytimg.com/vi/{x['id']}/hqdefault.jpg" alt="" width="480" height="360">{f'<span>{duration}</span>' if duration else ''}</a><div class="copy"><p class="tag">{e(x['format'])} · {e(x['language'])}</p><h3>{e(x['site'])}</h3><p class="by">By <a href="https://www.youtube.com/{e(c['handle'],quote=True)}">{e(c['name'])}</a></p><p>{e(x['note'])}</p><a class="watch" href="{url}">Watch on {e(c['name'])} ↗</a><a class="follow" href="https://www.youtube.com/{e(c['handle'],quote=True)}">Explore their channel ↗</a><a class="map" href="/?site={quote(x['site'],safe='')}">Explore this site on the map →</a></div></article>'''
    local=''.join(card(x) for x in selection['films'] if x['group']=='local')
    more=''.join(card(x) for x in selection['films'] if x['group']=='more')
    chapters=''.join(f'<li><a href="https://www.youtube.com/watch?v=q0YNkMIt3BY&amp;t={x["seconds"]}s">{e(x["label"])}</a></li>' for x in selection['chapters'])
    page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sardinia through its creators | The Ancient Atlas</title><meta name="description" content="Explore ancient Sardinia through local guides, on-site visits and Stone Riddles' full documentary. Watch the original films and follow their creators."><link rel="canonical" href="https://theancientatlas.com/creators/sardinia"><meta property="og:title" content="Sardinia through its creators"><meta property="og:image" content="https://theancientatlas.com/og-image.png"><link rel="icon" href="/favicon.ico"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Fraunces:opsz,wght@9..144,500&display=swap" rel="stylesheet"><style>
*{box-sizing:border-box}body{margin:0;background:#0D0D12;color:#F0EEE9;font:16px/1.65 Inter,system-ui,sans-serif}a{color:#D9BA69;text-underline-offset:4px}a:hover{color:white}.wrap{max-width:1180px;margin:auto;padding:0 clamp(20px,4vw,48px)}nav{display:flex;gap:24px;flex-wrap:wrap;padding:22px 0;border-bottom:1px solid #393540;font-size:14px}nav .brand{margin-right:auto;text-decoration:none}header{padding:40px 0 26px;max-width:800px}h1{font:500 clamp(40px,6vw,70px)/1.08 Fraunces,Georgia,serif;margin:14px 0 22px}h2{font:500 clamp(28px,4vw,40px)/1.2 Fraunces,Georgia,serif;margin:0 0 16px}h3{font:500 25px/1.25 Fraunces,Georgia,serif;margin:0 0 12px}.tag{font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:#D9BA69}.intro{font-size:19px;color:#C5C5D0}.feature{display:grid;grid-template-columns:1fr 1fr;background:#181820;border:1px solid #46404d;border-radius:6px;overflow:hidden;margin:10px 0 46px}.feature>a{display:flex;align-items:center;background:#08080b}.feature img{width:100%;height:auto;object-fit:contain}.feature .copy{padding:28px}.copy p{color:#C5C5D0}.feature ul{padding-left:20px;font-size:14px}.feature li{padding:3px 0}.feature .watch{display:inline-block;border:1px solid #D9BA69;padding:10px 15px}.by{font-weight:600}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin:24px 0 46px}article{min-width:0;background:#181820;border:1px solid #393540;border-radius:6px;overflow:hidden}.thumb{display:block;position:relative;aspect-ratio:16/9;overflow:hidden}.thumb img{width:100%;height:100%;object-fit:cover}.thumb span{position:absolute;right:10px;bottom:10px;background:#0D0D12;padding:2px 8px;font-size:13px}.copy{padding:24px}.watch,.follow,.map{display:block;margin-top:14px}.watch{font-weight:600}.follow,.map{font-size:14px}.note{color:#C5C5D0;max-width:75ch}footer{border-top:1px solid #393540;padding:30px 0;font-size:14px;color:#C5C5D0}:focus-visible{outline:3px solid #F0EEE9;outline-offset:5px}.skip{position:absolute;top:-80px;padding:12px;background:#0D0D12;z-index:4}.skip:focus{top:0}@media(max-width:680px){.feature,.grid{grid-template-columns:1fr}.feature img{aspect-ratio:16/9}.copy,.feature .copy{padding:20px}nav .brand{flex-basis:100%}}
</style><script defer src="/assets/js/analytics.js"></script><script data-goatcounter="https://ancientatlas.goatcounter.com/count" async src="//gc.zgo.at/count.js"></script></head><body><a class="skip" href="#main">Skip to films</a><div class="wrap"><nav aria-label="Main"><a class="brand" href="/">THE ANCIENT ATLAS</a><a href="/">Map</a><a href="/creators/">All creators</a><a href="/creators/ancient-atlas">Our films</a></nav><main id="main"><header><p class="tag">An island, many perspectives</p><h1>Sardinia through<br>its creators</h1><p class="intro">Step inside a nuraghe. Follow an archaeologist through a courtyard. See the island through the people who bring a camera and spend time on the ground.</p><p>Choose a visit below, watch the original film, and follow the creator for more.</p></header><section class="feature" aria-labelledby="deep"><a href="https://www.youtube.com/watch?v=q0YNkMIt3BY" aria-label="Watch Stone Riddles' full Sardinia documentary"><img src="https://i.ytimg.com/vi/q0YNkMIt3BY/hqdefault.jpg" alt="Stone Riddles II: Archaeological Treasures of Sardinia" width="480" height="360"></a><div class="copy"><p class="tag">The long watch · 2 h 19 min 40 s · English</p><h2 id="deep">Stone Riddles II</h2><p class="by">A film by <a href="https://www.youtube.com/@StoneRiddles">Stone Riddles / Mirko Kulig</a></p><p>Archaeological Treasures of Sardinia. A journey through nuraghi, giants’ tombs, sacred wells and rock-cut chambers, followed by the filmmaker’s interpretations.</p><a class="watch" href="https://www.youtube.com/watch?v=q0YNkMIt3BY">Watch the full documentary ↗</a><a class="follow" href="https://www.youtube.com/@StoneRiddles">Explore Stone Riddles’ channel ↗</a><details><summary>Start with a topic</summary><ul>'''+chapters+'''</ul><p class="note">Topic links follow the film’s YouTube chapter list.</p></details></div></section><section aria-labelledby="local"><p class="tag">Sardinian voices · Italian-language films</p><h2 id="local">Meet the people at the sites</h2><p class="note">Guided visits, on-site conversations and a short walk from creators with roots in Sardinian archaeology, heritage and travel. Original-language titles remain on the map.</p><div class="grid">'''+local+'''</div></section><section aria-labelledby="more"><h2 id="more">Keep exploring with other creators</h2><p class="note">More visits already on the Atlas. Compare perspectives and keep following the people behind the films.</p><div class="grid">'''+more+'''</div></section></main><footer>Curated 23 October 2026. Films remain on their creators’ YouTube channels.<br><a href="/creators/">Explore all creators</a> · <a href="https://www.youtube.com/@AncientAtlasMap">Follow Ancient Atlas</a> · <a href="/contact">Suggest a local creator</a></footer></div></body></html>'''
    (ROOT/'public/creators/sardinia.html').write_text(page)
if __name__=='__main__':main()
